    HeadersCtor = class Headers implements globalThis.Headers {
        private readonly headers = new Map<string, string[]>();
        constructor(init?: HeadersInit) {
            if (init instanceof HeadersCtor) init.forEach((value, key) => this.append(key, value));
            else if (Array.isArray(init)) for (const [key, value] of init) this.append(String(key), String(value));
            else if (init) for (const [key, value] of Object.entries(init)) this.append(key, String(value));
        }
        append(name: string, value: string): void { const key = name.toLowerCase(); this.headers.set(key, [...(this.headers.get(key) ?? []), value]); }
        delete(name: string): void { this.headers.delete(name.toLowerCase()); }
        get(name: string): string | null { const values = this.headers.get(name.toLowerCase()); return values ? values.join(", ") : null; }
