// Structural audit script — read-only analysis of the three specs.
// Usage: node struct.mjs (run from repo root with NODE_PATH pointing at repo node_modules)
import fs from "node:fs";
import path from "node:path";

const REPO = "/Users/15x/Downloads/WORKING/addons-me/clockify-ts-sdk";
const OFFICIAL = path.join(REPO, "spec/official/clockify.official.openapi.yaml");
const CORRECTED = path.join(REPO, "spec/corrected/clockify.corrected.openapi.yaml");
const LIVE = "/tmp/clockify-openapi-audit/official-live.json";

const YAML = (await import("yaml")).default;

function load(p) {
  const text = fs.readFileSync(p, "utf8");
  return p.endsWith(".json") ? JSON.parse(text) : YAML.parse(text);
}

const official = load(OFFICIAL);
const corrected = load(CORRECTED);
const live = load(LIVE);

const METHODS = ["get", "post", "put", "patch", "delete", "head", "options", "trace"];
const canonPath = (p) => String(p).replace(/^\/v1(?=\/)/, "").replace(/\{[^}]+\}/g, "{}");
const opKey = (m, p) => `${m.toUpperCase()} ${canonPath(p)}`;

function indexOps(doc) {
  const map = new Map();
  for (const [rawPath, item] of Object.entries(doc.paths ?? {})) {
    if (!item || typeof item !== "object") continue;
    for (const m of METHODS) {
      const op = item[m];
      if (!op || typeof op !== "object") continue;
      map.set(opKey(m, rawPath), { m, rawPath, op, item });
    }
  }
  return map;
}

const officialOps = indexOps(official);
const correctedOps = indexOps(corrected);
const liveOps = indexOps(live);

console.log("=== (b) operation/schema counts ===");
console.log(`official:    paths=${Object.keys(official.paths ?? {}).length} ops=${officialOps.size} schemas=${Object.keys(official.components?.schemas ?? {}).length}`);
console.log(`corrected:   paths=${Object.keys(corrected.paths ?? {}).length} ops=${correctedOps.size} schemas=${Object.keys(corrected.components?.schemas ?? {}).length}`);
console.log(`live json:   paths=${Object.keys(live.paths ?? {}).length} ops=${liveOps.size} schemas=${Object.keys(live.components?.schemas ?? {}).length}`);

// ---------- (a) $ref resolution ----------
function walkRefs(doc, label) {
  const refs = [];
  const seen = new Set();
  const stack = [];
  let cycles = 0;
  const unresolvable = new Set();

  function visit(value, where) {
    if (value === null || typeof value !== "object") return;
    if (Array.isArray(value)) { value.forEach((v, i) => visit(v, `${where}[${i}]`)); return; }
    if (typeof value.$ref === "string") {
      const ref = value.$ref;
      refs.push(ref);
      if (ref.startsWith("#/")) {
        if (seen.has(ref)) { cycles += 1; return; }
        seen.add(ref);
        const parts = ref.slice(2).split("/").map((t) => t.replace(/~1/g, "/").replace(/~0/g, "~"));
        let cur = doc;
        for (const part of parts) {
          if (cur == null || typeof cur !== "object" || !(part in cur)) { unresolvable.add(ref); break; }
          cur = cur[part];
        }
        if (cur && typeof cur === "object") visit(cur, ref);
        seen.delete(ref);
      }
      return;
    }
    for (const [k, v] of Object.entries(value)) visit(v, `${where}.${k}`);
  }
  visit(doc, "$");
  return { total: refs.length, distinct: new Set(refs).size, unresolvable: [...unresolvable], cycles };
}

for (const [label, doc] of [["official", official], ["corrected", corrected], ["live", live]]) {
  const r = walkRefs(doc, label);
  console.log(`(a) ${label}: $ref uses=${r.total} distinct=${r.distinct} unresolvable=${r.unresolvable.length} cycle-hits=${r.cycles}`);
  if (r.unresolvable.length) console.log(`    unresolvable: ${r.unresolvable.slice(0, 10).join(", ")}`);
}

// ---------- (c) x-clockify-live-status distribution (corrected) ----------
console.log("\n=== (c) corrected x-clockify-live-status distribution ===");
const dist = {};
for (const { op } of correctedOps.values()) {
  const s = op["x-clockify-live-status"] ?? "<unset>";
  dist[s] = (dist[s] ?? 0) + 1;
}
for (const [k, v] of Object.entries(dist).sort((a, b) => b[1] - a[1])) console.log(`  ${k}: ${v}`);

// ---------- (d) DOCUMENTED BUT BROKEN summaries ----------
console.log("\n=== (d) 'DOCUMENTED BUT BROKEN' (or similar) summaries in corrected ===");
const broken = [];
for (const { m, rawPath, op } of correctedOps.values()) {
  const sum = String(op.summary ?? "");
  if (/DOCUMENTED BUT BROKEN|NOT WORKING|BROKEN|DEAD ROUTE|returns?\s+404|not bound/i.test(sum)) {
    broken.push(`${m.toUpperCase()} ${rawPath} :: ${sum.slice(0, 110)}`);
  }
}
console.log(broken.length === 0 ? "  none" : broken.map((b) => `  ${b}`).join("\n"));

// ---------- (e) PHANTOM_PATHS presence in corrected ----------
console.log("\n=== (e) PHANTOM_PATHS entries present in corrected ===");
const generatorSrc = fs.readFileSync("/Users/15x/Downloads/WORKING/addons-me/GOCLMCP/scripts/gen-clockify-openapi", "utf8");
const ppBlock = generatorSrc.match(/PHANTOM_PATHS = \[(.*?)\n\]\.freeze/s)?.[1] ?? "";
const phantom = [...ppBlock.matchAll(/^\s*\["(get|post|put|patch|delete|head|options)",\s*"([^"]+)"/gm)].map((m2) => [m2[1].toLowerCase(), m2[2]]);
console.log(`  PHANTOM_PATHS entries parsed: ${phantom.length}`);
const correctedPaths = new Set(Object.keys(corrected.paths ?? {}));
const present = [];
for (const [m, p] of phantom) {
  // check op-level: does corrected have method+path (with any param names)?
  const pathItem = corrected.paths?.[p];
  if (pathItem && typeof pathItem[m] === "object") present.push(`${m.toUpperCase()} ${p}`);
  else if (pathItem === undefined) {
    // path may exist with different param names — check canonical
    const canon = canonPath(p);
    const hit = [...correctedOps.values()].find((o) => o.m.toLowerCase() === m && canonPath(o.rawPath) === canon);
    if (hit) present.push(`${m.toUpperCase()} ${p} (as ${hit.rawPath})`);
  }
}
console.log(present.length === 0 ? "  ALL 35 quarantined paths absent from corrected ✓" : `  STILL PRESENT (${present.length}):\n  ${present.join("\n  ")}`);

// ---------- (f) hash comparison ----------
console.log("\n=== (f) byte-identity spec/corrected vs GOCLMCP canonical ===");
const { createHash } = await import("node:crypto");
const h = (p) => createHash("sha256").update(fs.readFileSync(p)).digest("hex");
const corrHash = h(CORRECTED);
const goclmcpHash = h("/Users/15x/Downloads/WORKING/addons-me/GOCLMCP/docs/openapi/clockify-openapi.yaml");
console.log(`  corrected sha256: ${corrHash}`);
console.log(`  goclmcp   sha256: ${goclmcpHash}`);
console.log(`  byte-identical: ${corrHash === goclmcpHash}`);

// ---------- (g/h/i) corrected vs LIVE official per-op comparison ----------
console.log("\n=== (g/h/i) corrected vs live-official per-op comparison ===");
function paramsOf(op) {
  const out = [];
  for (const p of op.parameters ?? []) {
    if (p.$ref) { out.push({ ref: p.$ref }); continue; }
    out.push({ in: p.in, name: p.name, required: !!p.required, type: p.schema?.type ?? null, enum: p.schema?.enum ? p.schema.enum.join("|") : null });
  }
  return out;
}
function primaryResponseRef(op) {
  const codes = ["200", "201", "204"];
  for (const c of codes) {
    const r = op.responses?.[c];
    if (!r) continue;
    const content = r.content ?? r["content"] ?? {};
    for (const [, media] of Object.entries(content)) {
      if (media?.schema?.$ref) return media.schema.$ref.split("/").pop();
    }
  }
  return null;
}
function requestBodyRef(op) {
  const rb = op.requestBody;
  if (!rb) return null;
  const body = rb.$ref ? null : rb;
  if (!body) return null;
  for (const [, media] of Object.entries(body.content ?? {})) {
    if (media?.schema?.$ref) return media.schema.$ref.split("/").pop();
    if (media?.schema) return JSON.stringify(media.schema).slice(0, 60);
  }
  return null;
}

const sharedLive = [...liveOps.keys()].filter((k) => correctedOps.has(k));
console.log(`  shared ops (corrected vs live): ${sharedLive.length}`);
const liveOnly = [...liveOps.keys()].filter((k) => !correctedOps.has(k));
const correctedOnly = [...correctedOps.keys()].filter((k) => !liveOps.has(k));
console.log(`  live-only ops: ${liveOnly.length} | corrected-only ops: ${correctedOnly.length}`);
console.log(`  live-only:`);
for (const k of liveOnly.sort()) {
  const { rawPath, op } = liveOps.get(k);
  console.log(`    ${k}  (${rawPath}) opId=${op.operationId ?? "n/a"} deprecated=${!!op.deprecated}`);
}

// --- (h) response schema ref divergence ---
console.log("\n  (h) response schema name differs corrected vs live (same op):");
const respDiff = [];
for (const k of sharedLive) {
  const cRef = primaryResponseRef(correctedOps.get(k).op);
  const lRef = primaryResponseRef(liveOps.get(k).op);
  if (cRef && lRef && cRef !== lRef) respDiff.push({ k, corrected: cRef, live: lRef });
