const fs=require('fs');
const YAML=require('yaml');
const d=YAML.parse(fs.readFileSync('spec/corrected/clockify.corrected.openapi.yaml','utf8'));
const tagToResource=(t)=>t.replace(/[()]/g,' ').replace(/\s+([a-z])/g,(_,c)=>c.toUpperCase()).replace(/^./,c=>c.toLowerCase());
const resources=new Set();
let n=0;
for (const item of Object.values(d.paths)) for (const m of ['get','post','put','patch','delete']) {
  const op=item[m]; if(!op) continue; n++;
  resources.add(op['x-fern-sdk-group-name'] ?? tagToResource((op.tags||['Default'])[0]));
}
console.log('ops:',n,'| local-generator resource modules:',resources.size);
console.log('resources:',[...resources].sort().join(', '));
"

